import { render } from '@solidjs/web';
import { createSignal, createMemo, For, Loading, isPending, latest } from 'solid-js';
import './styles.css';

const tabs = ['Profile', 'Posts', 'Settings'];

async function fetchTab(tab) {
  await new Promise((resolve) => setTimeout(resolve, 800));
  return `This is the ${tab} page.`;
}

function App() {
  const [tab, setTab] = createSignal('Profile');
  const content = createMemo(() => fetchTab(tab()));

  return (
    <>
      <div class="tabs">
        <For each={tabs}>
          {(name) => (
            <button class={{ selected: tab() === name }} onClick={() => setTab(name)}>
              {name}
            </button>
          )}
        </For>
      </div>
      <Loading fallback={<p>Loading...</p>}>
        <div class="content">{content()}</div>
      </Loading>
    </>
  );
}

render(() => <App />, document.getElementById('app'));

body {
  font-family: sans-serif;
}

.tabs button {
  margin-right: 0.25rem;
  padding: 0.4rem 1rem;
  border: 1px solid #ccc;
  background: white;
}

.tabs button.selected {
  border-color: #446b9e;
  background: #446b9e;
  color: white;
}

.content {
  padding: 1rem 0;
  transition: opacity 0.2s;
}

.content.pending {
  opacity: 0.4;
}

import { render } from '@solidjs/web';
import { createSignal, createMemo, For, Loading, isPending, latest } from 'solid-js';
import './styles.css';

const tabs = ['Profile', 'Posts', 'Settings'];

async function fetchTab(tab) {
  await new Promise((resolve) => setTimeout(resolve, 800));
  return `This is the ${tab} page.`;
}

function App() {
  const [tab, setTab] = createSignal('Profile');
  const content = createMemo(() => fetchTab(tab()));

  return (
    <>
      <div class="tabs">
        <For each={tabs}>
          {(name) => (
            <button
              class={{ selected: latest(tab) === name }}
              onClick={() => setTab(name)}
            >
              {name}
            </button>
          )}
        </For>
      </div>
      <Loading fallback={<p>Loading...</p>}>
        <div class={{ content: true, pending: isPending(content) }}>{content()}</div>
      </Loading>
    </>
  );
}

render(() => <App />, document.getElementById('app'));

